import{_ as t,o as a,c as d,ag as o}from"./chunks/framework.CrXGS008.js";const b=JSON.parse('{"title":"API and webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"car-wash/api.md","filePath":"car-wash/api.md"}'),c={name:"car-wash/api.md"};function s(n,e,r,i,h,l){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="api-and-webhooks" tabindex="-1">API and webhooks <a class="header-anchor" href="#api-and-webhooks" aria-label="Permalink to &quot;API and webhooks&quot;">​</a></h1><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Grants</th></tr></thead><tbody><tr><td><code>nay_car_wash.config</code></td><td><code>/nay:carwash</code> (tunnel editor) and the Car Wash settings in <code>/nay</code>.</td></tr></tbody></table><p>Grant it with ACE or a rule, see <a href="/nay-lib/permissions">Permissions</a>.</p><h2 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h2><p>Turn the API on and create a token first, see <a href="/nay-lib/api">HTTP API</a>. Routes answer <code>{ &quot;ok&quot;: true, &quot;data&quot;: ... }</code> and need <code>Authorization: Bearer &lt;token&gt;</code>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Route</th><th>Scope</th><th>Query</th><th>Data</th></tr></thead><tbody><tr><td>GET</td><td><code>/nay_car_wash/v1/history</code></td><td><code>nay_car_wash.history.read</code></td><td><code>identifier</code>, <code>kind</code> (<code>tunnel</code> or <code>manual</code>), <code>limit</code> (1 to 100, default 20), <code>before</code> (id)</td><td><code>items</code> (<code>id</code>, <code>identifier</code>, <code>kind</code>, <code>location</code>, <code>program</code>, <code>price</code>, <code>time</code>), newest first, and <code>next</code>: pass it as <code>before</code> for the next page.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/stats</code></td><td><code>nay_car_wash.stats.read</code></td><td><code>days</code> (1 to 31, default 7), <code>utcOffset</code> (minutes, -720 to 840, default: the server clock)</td><td><code>utcOffset</code> used, <code>total</code>, <code>byDay</code> (every day listed) and <code>byLocation</code>, each with <code>washes</code> and <code>revenue</code>.</td></tr><tr><td>GET</td><td><code>/nay_car_wash/v1/tunnels</code></td><td><code>nay_car_wash.tunnels.read</code></td><td></td><td><code>index</code>, <code>label</code>, <code>enabled</code>, <code>entry</code> for each tunnel.</td></tr></tbody></table><p>Example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer nay_1_xxxxxxxx&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.example.com/nay_car_wash/v1/stats?days=7&quot;</span></span></code></pre></div><h2 id="webhook-events" tabindex="-1">Webhook events <a class="header-anchor" href="#webhook-events" aria-label="Permalink to &quot;Webhook events&quot;">​</a></h2><p>Pick them in the <strong>Webhooks</strong> tab of <code>/nay</code>, see <a href="/nay-lib/webhooks">Webhooks</a>.</p><table tabindex="0"><thead><tr><th>Event</th><th>When</th><th>Data</th></tr></thead><tbody><tr><td><code>nay_car_wash.wash</code></td><td>A tunnel wash is paid.</td><td><code>player</code> (name), <code>identifier</code>, <code>tunnel</code>, <code>program</code>, <code>price</code></td></tr><tr><td><code>nay_car_wash.manual</code></td><td>A pressure washer session ends.</td><td><code>player</code> (name), <code>identifier</code>, <code>station</code>, <code>price</code></td></tr></tbody></table><p>With a Discord webhook, each wash becomes an embed in your channel, in the server language.</p>',13)])])}const u=t(c,[["render",s]]);export{b as __pageData,u as default};
